-- =====================================================================
--  DATA AWAL (dibuat otomatis dari spreadsheet 16/10/2026)
--  Jalankan SETELAH 01_skema.sql. Aman dijalankan ulang: data yang sama
--  akan ditimpa dengan isi spreadsheet saat file ini dibuat.
-- =====================================================================
begin;

-- Admin yang boleh login dan mengubah data
on conflict (email) do update set nama = excluded.nama, aktif = true;

-- Kategori (5)
on conflict (kode) do update set nama = excluded.nama, nama_en = excluded.nama_en, label = excluded.label,
  ikon = excluded.ikon, deskripsi = excluded.deskripsi, deskripsi_en = excluded.deskripsi_en,
  target = excluded.target, urutan = excluded.urutan;

-- Kosakata (353)
on conflict (id) do update set sub = excluded.sub, tipe = excluded.tipe, indo = excluded.indo, en = excluded.en, fusha_ar = excluded.fusha_ar, fusha_lat = excluded.fusha_lat, mesir_ar = excluded.mesir_ar, mesir_lat = excluded.mesir_lat, saudi_ar = excluded.saudi_ar, saudi_lat = excluded.saudi_lat, catatan = excluded.catatan, catatan_en = excluded.catatan_en, sumber = excluded.sumber, status = excluded.status, dicek_oleh = excluded.dicek_oleh;

-- Tentang Saya (10)

Adapun alasan saya memilih jurusan Syariah Islamiah adalah karena jurusan ini mempelajari hukum-hukum Islam yang menjadi pedoman umat Muslim dalam kehidupan sehari-hari. Saya berharap ilmu yang dipelajari dapat menjadi bekal bagi diri sendiri agar mampu menjalani kehidupan sesuai tuntunan syariat, sekaligus bermanfaat bagi masyarakat dalam memahami dan menjawab berbagai persoalan hukum Islam.', 'I chose Egypt as the place to pursue my studies because its education system encourages students to be independent, manage their own time, and take responsibility for their own learning. Egypt is also one of the centers of Islamic scholarship, offering many opportunities to deepen knowledge and grow as a person.

I chose the Islamic Sharia department because it studies Islamic law, which guides Muslims in their daily lives. I hope what I learn will be a foundation for myself to live according to the teachings of the Sharia, and also benefit society in understanding and answering questions about Islamic law.', 7),
  ('paragraf_2', 'Paragraf 2: Awal datang', 'Kesan pertama, kaget budaya, dan tantangan di minggu-minggu awal', 'Menurut saya, kesan pertama datang ke Mesir cukup mengejutkan karena ternyata Mesir tidak seperti yang saya bayangkan sebelumnya. Tantangan di minggu-minggu awal adalah beradaptasi dengan cuaca dingin, mengatasi homesick karena belum terbiasa merantau, serta memberanikan diri untuk keluar rumah dan berinteraksi dengan masyarakat Mesir meskipun saat itu saya belum memahami bahasanya. Namun, saya tetap berusaha agar kemampuan bahasa saya terus berkembang.', 'My first impression of Egypt was quite a surprise, because it turned out to be different from what I had imagined. The challenges in the first few weeks were adapting to the cold weather, dealing with homesickness since I wasn''t used to living away from home, and finding the courage to go out and interact with Egyptians even though I didn''t understand the language yet. Still, I kept trying so that my language skills would keep improving.', 8),
  ('paragraf_3', 'Paragraf 3: Soal bahasa', 'Pengalaman menyesuaikan diri dengan ''Ammiyah Mesir padahal belajarnya Fusha', 'Tantangan saya dalam menyesuaikan diri dengan bahasa Arab sehari-hari adalah perbedaan antara fusha yang saya pelajari secara formal dengan amiyah Mesir. Perbedaannya meliputi pola penyusunan kalimat, pelafalan beberapa huruf, serta penggunaan ungkapan yang lebih singkat. Contohnya, huruf jim yang sering dilafalkan seperti bunyi “g” dalam amiyah Mesir. Pada awalnya, hal ini membuat saya kesulitan memahami percakapan masyarakat setempat. Karena itu, saya perlu membiasakan diri untuk memahami pola dan kebiasaan bahasa mereka melalui interaksi sehari-hari.', 'My challenge in adjusting to everyday Arabic was the difference between the Fusha I had learned formally and Egyptian ''Ammiyah. The differences include sentence structure, the pronunciation of some letters, and the use of shorter expressions. For example, the letter jim is often pronounced like a "g" in Egyptian ''Ammiyah. At first, this made it hard for me to follow conversations with local people. So I had to get used to their language patterns and habits through daily interaction.', 9),
  ('paragraf_4', 'Paragraf 4: Pesan untuk maba', 'Saran singkat untuk adik-adik yang mau atau baru datang ke Mesir', 'Untuk adik-adik yang ingin datang ke Mesir, persiapkan niat dan kuatkan tujuan kalian untuk menuntut ilmu. Ketika suatu saat merasa futur, kehilangan semangat, atau tidak memiliki teman yang bisa diandalkan, ingat kembali tujuan awal kalian datang ke Mesir. Selain itu, carilah lingkungan dan teman yang mendukung proses belajar, karena pergaulan sangat berpengaruh terhadap perjalanan kalian. Terakhir, persiapkan mental untuk menghadapi berbagai proses adaptasi, mulai dari bahasa, cuaca, hingga budaya masyarakat setempat. Semoga Allah menjaga niat dan langkah kita dalam menuntut ilmu.', 'To those of you planning to come to Egypt: prepare your intention and strengthen your purpose in seeking knowledge. When you one day feel worn out, lose your motivation, or have no friends to rely on, remember the reason you came to Egypt in the first place. Also, look for an environment and friends who support your learning, because the company you keep strongly shapes your journey. Finally, prepare yourself mentally for the many adjustments ahead, from the language and the weather to the local culture. May Allah protect our intentions and our steps in seeking knowledge.', 10)
on conflict (kunci) do update set bagian = excluded.bagian, panduan = excluded.panduan, isi = excluded.isi,
  isi_en = excluded.isi_en, urutan = excluded.urutan;

-- Administrasi (0 langkah terisi)

-- Panduan untuk website (10 baris)
 ''Ammiyah Mesir: yang benar-benar didengar di jalan, pasar, dan kampus di Mesir.
 Madinah (Hijazi): pembanding, supaya terlihat satu makna bisa diucapkan berbeda.', 'Fusha: standard Arabic that most students have already learned in Indonesia, and the language of the Qur''an and hadith
''Ammiyah Mesir (Egyptian Arabic): what you actually hear on the street, at the market, and on campus in Egypt.
Madinah (Hijazi): a point of comparison, to show how one meaning can be said in different ways.', 2),
  ('prinsip', 'Prinsip cara baca', 'Latin hanya bantuan cara baca, bukan pengganti tulisan Arab. Pakai pola transliterasi yang biasa dipakai di pesantren Indonesia:', 'Latin script is only a pronunciation aid, not a replacement for Arabic script. It follows the transliteration style commonly used in Indonesian pesantren:', 3),
  ('baca_01', 'ث / ذ', 'ts / dz', null, 4),
  ('baca_02', 'ح / خ', 'h / kh', null, 5),
  ('baca_03', 'ش / ص', 'sy / sh', null, 6),
  ('baca_04', 'ض / ط / ظ', 'dh / th / zh', null, 7),
  ('baca_05', 'ع / غ', '(apostrof) / gh', '(apostrophe) / gh', 8),
  ('baca_06', 'Vokal panjang', 'aa, ii, uu (contoh: kitaab)', 'aa, ii, uu (example: kitaab)', 9),
  ('baca_07', 'Khas Mesir', 'ج dibaca g (gamal), ق dibaca seperti hamzah (qalam → ''alam), ث sering jadi t', 'ج is pronounced g (gamal), ق is pronounced like a hamza (qalam → ''alam), ث often becomes t', 10)
on conflict (kunci) do update set label = excluded.label, isi = excluded.isi, isi_en = excluded.isi_en, urutan = excluded.urutan;

-- Catatan impor: ganti ratusan baris log 'tambah' dengan satu ringkasan
delete from public.log_admin where pelaku = 'SQL editor';
  jsonb_build_object('kategori', 5, 'kosakata', 353, 'tentang', 10, 'administrasi', 0, 'panduan', 10));

commit;

-- Cek hasil (harus sama dengan angka di komentar di atas):
select (select count(*) from public.kategori) as kategori, (select count(*) from public.kosakata) as kosakata,
       (select count(*) from public.tentang) as tentang, (select count(*) from public.panduan) as panduan,
       (select count(*) from public.admin) as admin;
