insert into public.tentang (kunci, bagian, panduan, isi, isi_en, urutan) values
  ('nama', 'Nama', 'Nama yang mau ditampilkan di website', 'Abrar Akhmad Ridho', 'Abrar Akhmad Ridho', 1),
  ('asal', 'Asal daerah', 'Kota atau kabupaten asal di Indonesia', 'Bekasi', 'Bekasi', 2),
  ('kampus', 'Kampus & jurusan', 'Nama universitas, fakultas, dan jurusan', 'Al Azhar, syariah wal qonun, syariah islamiyyah', 'Al-Azhar University, Faculty of Sharia and Law, Islamic Sharia department', 3),
  ('angkatan', 'Tahun tiba di Mesir', 'Tahun pertama datang dan tingkat/semester sekarang', 'tahun 2023, tingkat 2', 'Arrived in 2023, now in year 2', 4),
  ('foto', 'Link foto (opsional)', 'Link foto profil, misalnya dari Google Drive yang dibuka aksesnya', 'https://drive.google.com/file/d/1wBPHDzqnMxGYI-rFQzyFpxUhhcYuVM0_/view?usp=drivesdk', 'https://drive.google.com/file/d/1wBPHDzqnMxGYI-rFQzyFpxUhhcYuVM0_/view?usp=drivesdk', 5),
  ('kontak', 'Kontak (opsional)', 'Media sosial atau email yang boleh dilihat publik. Jangan nomor HP pribadi', 'ig; @abrrkhmdr', 'ig; @abrrkhmdr', 6),
  ('paragraf_1', 'Paragraf 1: Kenapa Mesir?', 'Alasan memilih kuliah di Mesir dan jurusan ini', 'Saya memilih Mesir sebagai tempat menuntut ilmu karena sistem pendidikannya mendorong mahasiswa untuk mandiri, mampu mengatur waktu, dan bertanggung jawab atas proses belajarnya sendiri. Selain itu, Mesir merupakan salah satu pusat keilmuan Islam yang menyediakan banyak kesempatan untuk memperdalam ilmu dan mengembangkan diri.
insert into public.panduan (kunci, label, isi, isi_en, urutan) values
  ('tujuan', 'Tujuan', 'Membantu mahasiswa baru (maba) dari Indonesia yang baru pindah ke Mesir supaya cepat bisa berkomunikasi di situasi sehari-hari.', 'To help new students from Indonesia who have just moved to Egypt communicate quickly in everyday situations.', 1),
  ('kenapa', 'Kenapa 3 bahasa?', 'Fusha: bahasa Arab baku yang umumnya sudah dipelajari di Indonesia, atau bahasa yang digunakan di Al Qur''an dan hadist
